  put('hd_m3', 3, 'fig', '<svg viewBox="0 0 230 164" class="lz-fig" role="img" aria-label="楕円x²/8+y²/2=1上の点(2, 1)における接線。x²を2x、y²を1·yに置きかえて2x/8+y/2=1、つまりx+2y=4"><line x1="10" y1="82" x2="210" y2="82" class="ax"/><path d="M205.5 84.2 L210 82 L205.5 79.8" class="ax"/><line x1="92" y1="126" x2="92" y2="8" class="ax"/><path d="M94.2 12.5 L92 8 L89.8 12.5" class="ax"/><text x="208" y="95" text-anchor="end">x</text><text x="97" y="17">y</text><ellipse cx="92" cy="82" rx="73.5" ry="36.8" class="cv"/><line x1="86.8" y1="27.4" x2="216.8" y2="92.4" class="cv2"/><circle cx="144" cy="56" r="3" class="pt"/><text x="148" y="50">(2, 1)</text><text x="193" y="95" text-anchor="end">4</text><text x="86" y="34" text-anchor="end">2</text><text x="224" y="18" text-anchor="end">x²/8 + y²/2 = 1</text><text x="115" y="140" text-anchor="middle">4/8 + 1/2 = 1 で曲線上(前提 OK)</text><text x="115" y="156" text-anchor="middle">2x/8 + 1·y/2 = 1 → x + 2y = 4</text></svg>');
